import type { Context } from '@deepseek-ai/cordis'
import type { Agent } from '@deepseek-ai/dsh-agent'
import * as ToolBash from '@deepseek-ai/dsh-tool-bash'
import type { ToolRuntime } from '@deepseek-ai/dsh-tools'
import type { SystemPrompt } from '@deepseek-ai/dsh-system-prompt'
import type { ShellExecRequest } from '@deepseek-ai/dsh-shell'

import { note, skip, warn, type SkipReason } from './diag.ts'
import { executorConfig, type ConfigSnapshot } from './config.ts'
import { GitBashExecutor } from './executor.ts'
import { bashInstallRoot, bashPathEntries } from './paths.ts'
import { discoverBash } from './discover.ts'
import { CmdExecutor } from './cmd/executor.ts'
import { discoverCmd } from './cmd/discover.ts'
import { CMD_PROMPT_SECTION } from './cmd/prompt.ts'
import * as ToolCmd from './cmd/tool.ts'
import { MINIMAL_ID, VARIANT_ID } from './preset.ts'

/**
 * Per-session replacement.
 *
 * The plugin never takes over `ctx.shell` globally and never edits preset
 * files. Instead, when a session is announced it builds a private isolate
 * subtree for that one agent, mounts the bash executor and the stock
 * `tool-bash` inside it, and then hides `pwsh` from that agent's view:
 *
 * - the shell executor lives behind `isolate('shell', ...)`, so only plugins
 *   mounted on that subtree can see it — every other agent, and the host
 *   itself, keeps the platform's executor;
 * - `tool-bash` registers `bash` through the subtree context, which carries the
 *   agent's scope tag, so the tool lands in the agent's own tool layer;
 * - `restrict({ deny: ['pwsh'] })` only filters what the agent *inherits*, so
 *   it removes the preset's `pwsh` tool while leaving every other preset tool
 *   untouched;
 * - a same-named prompt section with empty text removes the `pwsh` guidance
 *   section (empty sections are dropped at render time).
 *
 * Every step is idempotent and every failure is contained: a session that
 * cannot be replaced keeps the stock pwsh tool and records why.
 */

/** Marker in the diagnostic log and the isolate label. */
const TAG = 'terminal-shell'

/** Fallback order for the `tool:pwsh` prompt section when the table lookup fails. */
const TOOL_PWSH_ORDER = 1010
/** `TOOL_BASH` in `@deepseek-ai/dsh-system-prompt`; fallback when unregistered. */
const TOOL_BASH_ORDER = 1000

/**
 * What a session-level attempt produced, for tests and diagnostics.
 *
 * `bashPath` is deliberately **not** renamed to a neutral `executable`: it is
 * written into generated preset rows (`src/preset.ts:110`) and used as the PTY
 * backend's config key, so renaming it would drag a client-visible schema change
 * into this release. The cmd path is therefore an *additional* optional field.
 */
export type InstallResult =
  | { readonly status: 'installed'; readonly bashPath: string; readonly cmdPath?: string }
  | { readonly status: 'skipped'; readonly reason: SkipReason; readonly detail?: string }

/**
 * Services are probed rather than injected: this plugin is loaded at profile
 * root, and a composition that lacks one of them must degrade to "leave the
 * session alone" instead of failing to load.
 */
function optional<T>(ctx: Context, name: string): T | undefined {
  return ctx.get(name) as T | undefined
}

/** Session preset of an agent, read from the projection with a header fallback. */
function presetOf(agentCtx: Context, agent: Agent): string | undefined {
  const projections = optional<{
    stateOf(session: unknown, key: string): unknown
  }>(agentCtx, 'sessionProjections')
  const projected = projections?.stateOf(agent.session, 'agentPreset')
  if (typeof projected === 'string') return projected
  const header = (agent.session as { header?: { agentPreset?: string } }).header
  return header?.agentPreset
}

/**
 * Replace one session's terminal tool.
 *
 * Runs inside `agent/created`, which is dispatched serially: a throw here fails
 * agent creation, so the whole body is defensive and always resolves.
 */
export async function installSession(
  ctx: Context,
  agent: Agent,
  snapshot: ConfigSnapshot,
): Promise<InstallResult> {
  const id = String(agent.id)

  if (process.platform !== 'win32') return { status: 'skipped', reason: skip(id, 'not-win32') }

  const agentCtx = agent.ctx
  if (agentCtx === undefined) return { status: 'skipped', reason: skip(id, 'no-agent-context') }

  // A preset decides which terminal stack the session gets. Two presets are
  // left entirely alone here:
  //
  // - `minimal-gitbash` (this plugin's variant) already mounts the persistent
  //   Git Bash backend; adding a one-shot `bash` would collide with it;
  // - `minimal` under `minimalMode: leave|variant` keeps the official persistent
  //   terminal (pwsh on Windows) by explicit user choice.
  //
  // Read the projection, not the header: switching presets before the first
  // turn only appends `agent-preset/selected`.
  const preset = presetOf(agentCtx, agent)
  if (preset === VARIANT_ID) return { status: 'skipped', reason: skip(id, 'already-replaced') }
  if (preset === MINIMAL_ID && snapshot.minimalMode !== 'oneshot') {
    return { status: 'skipped', reason: skip(id, 'minimal-left', snapshot.minimalMode) }
  }

  // The dialect gate lives *here* — after the preset guards and before any
  // mount — for two reasons:
  //
  // 1. Above the preset guards it would bypass the "leave the preset alone"
  //    semantics: under `minimalMode: variant` the persistent terminal preset
  //    already owns the terminal, and mounting a cmd tool next to it would give
  //    the agent two terminal tools; worse, denying `pwsh`/`bash` there would
  //    strip the preset's own tools.
  // 2. It must come after `agentCtx` is read, because `installCmdSession` takes
  //    that context and a declaration-order mistake is a TS2448.
  if (snapshot.dialect === 'pwsh') return { status: 'skipped', reason: skip(id, 'dialect-pwsh') }
  if (snapshot.dialect === 'cmd') return installCmdSession(agent, agentCtx, snapshot)

  const tools = optional<ToolRuntime>(agentCtx, 'tools')
  const systemPrompt = optional<SystemPrompt>(agentCtx, 'systemPrompt')
  if (tools === undefined) return { status: 'skipped', reason: skip(id, 'missing-service', 'tools') }
  if (systemPrompt === undefined) {
    return { status: 'skipped', reason: skip(id, 'missing-service', 'systemPrompt') }
  }

  // Idempotency: if a `bash` tool already exists in this agent's view — a retry,
  // a custom preset that ships one, or a previous install that survived — do
  // nothing. Registering a second one would throw inside the tool layer.
  if (tools.get('bash', agent) !== undefined) {
    return { status: 'skipped', reason: skip(id, 'already-replaced') }
  }

  // Resolve bash before touching the tree so a missing installation has no
  // side effects at all.
  const discovery = await discoverBash({
    bashPath: snapshot.bashPath,
    bashCandidates: snapshot.bashCandidates,
    autoDiscover: snapshot.autoDiscover,
    timeoutMs: snapshot.discoverTimeoutMs,
  })
  const found = discovery.found
  if (found === undefined) {
    const detail =
      discovery.rejected.length === 0
        ? `no candidate found (${discovery.considered.length} considered)`
        : discovery.rejected.map((item) => `${item.path}: ${item.reason}`).join('; ')
    return { status: 'skipped', reason: skip(id, 'bash-not-found', detail) }
  }

  const installRoot = bashInstallRoot(found.path)
  const pathEntries = bashPathEntries(installRoot, snapshot.extraPath)

  // Everything created below is registered on `agentCtx`, so cordis unwinds it
  // when the agent is disposed. The explicit list exists only to roll back a
  // *partial* install inside this function.
  const undo: (() => void)[] = []
  const fibers: { dispose: () => Promise<void> }[] = []

  try {
    // The private shell realm for this agent. Without a label every call
    // creates a fresh isolate symbol, which is exactly the intended privacy:
    // this executor is visible only to plugins mounted on `shellCtx`.
    const shellCtx = agentCtx.isolate('shell')

    const executorHost = await shellCtx.plugin(GitBashExecutor, {
      ...executorConfig(snapshot),
      bashPath: found.path,
      pathEntries,
      loginShell: snapshot.loginShell,
      pythonUtf8: snapshot.pythonUtf8,
    })
    fibers.push(executorHost)

    const toolHost = await shellCtx.plugin(ToolBash, {
      enableRunInBackground: true,
      promoteOnTimeout: true,
    })
    fibers.push(toolHost)

    // Verify the mount produced the tool before hiding pwsh: if `bash` never
    // appeared, restricting `pwsh` would leave the agent with no terminal tool.
    // Throwing here routes into the same reverse rollback as any other failure —
    // returning early would leave the mounted subtree alive for the rest of the
    // session while the session itself stayed on pwsh.
    if (tools.get('bash', agent) === undefined) {
      throw new Error('tool-bash mounted but did not register a bash tool')
    }

    // Hide the platform tool. `restrict()` validates names against the tools the
    // agent inherits, so a composition without `pwsh` must skip rather than throw.
    if (tools.get('pwsh', agent) !== undefined) {
      undo.push(tools.restrict({ deny: ['pwsh'] }))
      // Dropping the pwsh guidance is a nice-to-have: the section registry
      // rejects a duplicate name inside one scope, and failing the whole install
      // over a shadowed prompt section would leave the session on pwsh for no
      // good reason. The bash tool is already what makes the session work.
      try {
        undo.push(
          systemPrompt.section({
            name: 'tool:pwsh',
            order: systemPrompt.getSectionOrder('TOOL_PWSH') ?? TOOL_PWSH_ORDER,
            text: '',
          }),
        )
      } catch (error) {
        warn(id, `cannot shadow the tool:pwsh prompt section: ${error instanceof Error ? error.message : String(error)}`)
      }
    } else {
      warn(id, 'no inherited pwsh tool to hide; leaving the inherited tool list alone')
    }

    // Hand the disposers to the agent's fiber so they run in reverse order when
    // the session ends.
    agentCtx.effect(() => () => {
      for (const disposer of undo.reverse()) {
        try {
          disposer()
        } catch {
          // Disposal is best-effort; the fiber tree is the real safety net.
        }
      }
    })

    note(id, `bash=${found.path} source=${found.source} path=${pathEntries.length} entries`)
    return { status: 'installed', bashPath: found.path }
  } catch (error) {
    // Reverse rollback: newest first, so a half-mounted subtree is unwound in
    // the order cordis itself would use.
    for (const disposer of undo.reverse()) {
      try {
        disposer()
      } catch {
        // ignore
      }
    }
    for (const fiber of fibers.reverse()) {
      try {
        await fiber.dispose()
      } catch {
        // ignore
      }
    }
    const detail = error instanceof Error ? error.message : String(error)
    return { status: 'skipped', reason: skip(id, 'mount-failed', detail) }
  }
}

/**
 * Install the cmd dialect into one agent's scope.
 *
 * Structurally identical to the bash path, with three differences that are
 * load-bearing:
 *
 * 1. It takes `agentCtx` and never the root context. `tools.restrict()` throws on
 *    a context-global scope ("a context-global restriction would mask every
 *    agent"), and `systemPrompt.section()` on the root would leak the `tool:cmd`
 *    section — and the blanked `tool:pwsh` one — into every session.
 * 2. It denies *both* inherited shell tools, but only the ones actually visible:
 *    `restrict` rejects unknown names, and a preset may have re-mounted
 *    `tool-bash` inside the preset's shared scope even on Windows.
 * 3. The `tool:cmd` section is registered here and nowhere else. `NamedEntries`
 *    throws on a duplicate name in one scope, so `ToolCmd.apply()` must not also
 *    register it.
 */
async function installCmdSession(
  agent: Agent,
  agentCtx: Context,
  snapshot: ConfigSnapshot,
): Promise<InstallResult> {
  const id = String(agent.id)

  const tools = optional<ToolRuntime>(agentCtx, 'tools')
  const systemPrompt = optional<SystemPrompt>(agentCtx, 'systemPrompt')
  if (tools === undefined) return { status: 'skipped', reason: skip(id, 'missing-service', 'tools') }
  if (systemPrompt === undefined) {
    return { status: 'skipped', reason: skip(id, 'missing-service', 'systemPrompt') }
  }

  // Idempotency: a retry, or a previous install that survived, already has `cmd`.
  if (tools.get('cmd', agent) !== undefined) {
    return { status: 'skipped', reason: skip(id, 'already-replaced') }
  }

  // Resolve cmd.exe before touching the tree, so a broken configuration has no
  // side effects at all.
  const found = discoverCmd(snapshot.cmdPath)
  if (found === undefined) {
    return {
      status: 'skipped',
      reason: skip(id, 'cmd-not-found', 'no cmd.exe via cmdPath, ComSpec or %SystemRoot%'),
    }
  }
  if (snapshot.cmdCodePage !== 65001) {
    warn(
      id,
      `cmdCodePage=${snapshot.cmdCodePage}: the harness decodes child output as UTF-8, so non-ASCII output will contain replacement characters`,
    )
  }

  const undo: (() => void)[] = []
  const fibers: { dispose: () => Promise<void> }[] = []

  try {
    const shellCtx = agentCtx.isolate('shell')

    const executorHost = await shellCtx.plugin(CmdExecutor, {
      ...executorConfig(snapshot),
      cmdPath: found.path,
      pathEntries: [...snapshot.extraPath],
      codePage: snapshot.cmdCodePage,
      pythonUtf8: snapshot.pythonUtf8,
      confinedPolicy: snapshot.cmdConfinedPolicy,
    })
    fibers.push(executorHost)

    const toolHost = await shellCtx.plugin(ToolCmd, {
      enableRunInBackground: true,
      promoteOnTimeout: true,
    })
    fibers.push(toolHost)

    // Verify the mount produced the tool before hiding anything: if `cmd` never
    // appeared, denying the inherited tools would leave the agent with no
    // terminal tool at all.
    if (tools.get('cmd', agent) === undefined) {
      throw new Error('tool-cmd mounted but did not register a cmd tool')
    }

    const inherited = ['pwsh', 'bash'].filter((name) => tools.get(name, agent) !== undefined)
    if (inherited.length > 0) {
      undo.push(tools.restrict({ deny: inherited }))
      for (const name of inherited) {
        const section = name === 'pwsh' ? 'tool:pwsh' : 'tool:bash'
        try {
          undo.push(
            systemPrompt.section({
              name: section,
              order:
                systemPrompt.getSectionOrder(name === 'pwsh' ? 'TOOL_PWSH' : 'TOOL_BASH') ??
                (name === 'pwsh' ? TOOL_PWSH_ORDER : TOOL_BASH_ORDER),
              text: '',
            }),
          )
        } catch (error) {
          warn(
            id,
            `could not blank the ${section} prompt section: ${error instanceof Error ? error.message : String(error)}`,
          )
        }
      }
    } else {
      warn(id, 'no inherited shell tool to hide; leaving the inherited tool list alone')
    }

    // `tool:cmd` shares the order of the section it replaces: exactly one shell
    // tool is described to the model, in the slot the shell section always had.
    // Guarded like the bash path: a section registry that already holds this
    // name must not fail the whole install (the tool is what makes it work).
    try {
      undo.push(
        systemPrompt.section({
          name: 'tool:cmd',
          order: systemPrompt.getSectionOrder('TOOL_PWSH') ?? TOOL_PWSH_ORDER,
          text: CMD_PROMPT_SECTION,
        }),
      )
    } catch (error) {
      warn(id, `cannot register the tool:cmd prompt section: ${error instanceof Error ? error.message : String(error)}`)
    }

    agentCtx.effect(() => () => {
      for (const disposer of undo.reverse()) {
        try {
          disposer()
        } catch {
          // Disposal is best-effort; the fiber tree is the real safety net.
        }
      }
    })

    note(
      id,
      `cmd=${found.path} source=${found.source} codepage=${snapshot.cmdCodePage} confined=${snapshot.cmdConfinedPolicy}`,
    )
    // `bashPath` carries the executable on both dialects until the field is
    // renamed in a separate change: `src/index.ts` and `src/routes.ts` read it.
    return { status: 'installed', bashPath: found.path, cmdPath: found.path }
  } catch (error) {
    for (const disposer of undo.reverse()) {
      try {
        disposer()
      } catch {
        // ignore
      }
    }
    for (const fiber of fibers.reverse()) {
      try {
        await fiber.dispose()
      } catch {
        // ignore
      }
    }
    const detail = error instanceof Error ? error.message : String(error)
    return { status: 'skipped', reason: skip(id, 'cmd-mount-failed', detail) }
  }
}

/** Re-exported so the selftest can build a request without importing the shell package. */
export type { ShellExecRequest }
